svg.script:
(function () {
  function boot() {
    var srcEl = document.getElementById('original-html');
    var frame = document.getElementById('game-frame');
    if (!srcEl || !frame) {
      // Retry once the DOM is fully built.
      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', boot, { once: true });
      }
      return;
    }
    frame.srcdoc = srcEl.textContent.replace(/^\s+/, '');
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot, { once: true });
  } else {
    boot();
  }
})();
